SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, DATE_TRUNC('WEEK', started_at) AS week_start, COUNT(CASE WHEN country = 'DE' THEN 1 END) AS de_count, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes_2, COUNT(DISTINCT country) AS distinct_countries, COUNT(DISTINCT browser) AS distinct_browsers FROM sessions GROUP BY DATE_TRUNC('QUARTER', started_at), DATE_TRUNC('WEEK', started_at) ORDER BY span_minutes DESC NULLS LAST;
